"""Fill the pilot's markdown and HTML templates with the exact old lines of FACTS.md and the new drafts.

Usage: python3 -I build.py REPO SCRATCH
"""
import html, re, sys

repo, scratch = sys.argv[1], sys.argv[2]
NUMS = ['F-252', 'F-53', 'F-396', 'F-63']

old = {}
for line in open(repo + '/explorations/coordinator/FACTS.md', encoding='utf-8'):
    line = line.rstrip('\n')
    for n in NUMS:
        if line.startswith('- ' + n + ' '):
            old[n] = line
assert len(old) == 4, old.keys()

new = {}
for line in open(scratch + '/drafts.txt', encoding='utf-8'):
    line = line.rstrip('\n')
    if '|' in line:
        n, text = line.split('|', 1)
        new[n] = re.sub(r' +', ' ', text).strip()
assert len(new) == 4

def plain(t):
    return re.sub(r' +', ' ', t.replace('|EV|', '').replace('|/EV|', '')).strip()

def md_new(t):
    return '> ' + re.sub(r' +', ' ', t.replace('|EV|', '<mark>').replace('|/EV|', '</mark>')).strip()

def inline_html(t):
    """Markdown code spans and bold to HTML, with everything else escaped."""
    out, i = [], 0
    parts = re.split(r'(`[^`]*`)', t)
    for p in parts:
        if p.startswith('`') and p.endswith('`') and len(p) >= 2:
            out.append('<code>' + html.escape(p[1:-1], quote=False) + '</code>')
        else:
            e = html.escape(p, quote=False)
            e = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', e)
            out.append(e)
    return ''.join(out)

def html_entry(t, mark):
    t = t[2:] if t.startswith('- ') else t
    if mark:
        a, rest = t.split('|EV|', 1)
        ev, b = rest.split('|/EV|', 1)
        body = inline_html(a.rstrip()) + ' <span class="ev">' + inline_html(ev.strip()) + '</span> ' + inline_html(b.lstrip())
    else:
        body = inline_html(t)
    # bold spanning code spans: the title holds code spans, so mark it after the split
    return body.strip()

def html_title_fix(h):
    # the title is between the first ** and the next **, which may hold <code>; redo it on the HTML
    return h

# Bold titles can contain code spans, which the per-part split above breaks. Handle the title first.
def entry_to_html(t, mark):
    t = t[2:] if t.startswith('- ') else t
    m = re.match(r'(F-\d+) \*\*(.+?)\*\*(.*)$', t)
    num, title, rest = m.group(1), m.group(2), m.group(3)
    title_h = inline_html(title)
    if mark:
        a, r2 = rest.split('|EV|', 1)
        ev, b = r2.split('|/EV|', 1)
        rest_h = inline_html(a.rstrip()) + ' <span class="ev">' + inline_html(ev.strip()) + '</span> ' + inline_html(b.lstrip())
    else:
        rest_h = inline_html(rest)
    return (num + ' <strong>' + title_h + '</strong>' + rest_h).strip()

lens = {n: (len(old[n]), len(plain(new[n])), len(re.sub(r' +', ' ', re.sub(r'\|EV\|.*?\|/EV\|', '', new[n])).strip())) for n in NUMS}
for n in NUMS:
    print(n, lens[n])
print('total', [sum(lens[n][i] for n in NUMS) for i in range(3)])

md = open(scratch + '/pilot.template.md', encoding='utf-8').read()
for n in NUMS:
    md = md.replace('{NEW_' + n + '}', md_new(new[n]))
    md = md.replace('{OLD_' + n + '}', '> ' + old[n])
assert '{NEW_' not in md and '{OLD_' not in md
open(sys.argv[3], 'w', encoding='utf-8').write(md)

page = open(scratch + '/page.template.html', encoding='utf-8').read()
for n in NUMS:
    page = page.replace('{NEWHTML_' + n + '}', entry_to_html(new[n], True))
    page = page.replace('{OLDHTML_' + n + '}', entry_to_html(old[n], False))
assert '{NEWHTML_' not in page and '{OLDHTML_' not in page
open(scratch + '/page.html', 'w', encoding='utf-8').write(page)
print('written')

